def reserve(stock, payload):
    sku = payload.get("sku")
    quantity = payload.get("quantity", 1)
    if not isinstance(sku, str):
        return 400, {"error": "invalid SKU"}
    if isinstance(quantity, bool) or not isinstance(quantity, int) or quantity <= 0:
        return 400, {"error": "invalid quantity"}
    return _reserve(stock, sku, quantity)

def _reserve(stock, sku, quantity):
    if stock.get(sku, 0) < quantity:
        return 409, {"error": "insufficient stock"}
    stock[sku] = stock.get(sku, 0) - quantity
    return 200, {"reserved": quantity}

