import unittest
from inventory import reserve

class ReservationTests(unittest.TestCase):
    def test_negative_quantity_is_rejected(self):
        stock = {"widget": 10}
        self.assertEqual(reserve(stock, {"sku": "widget", "quantity": -2})[0], 400)
        self.assertEqual(stock["widget"], 10)

    def test_reserve_stock(self):
        stock = {"widget": 10}
        self.assertEqual(reserve(stock, {"sku": "widget", "quantity": 2})[0], 200)
        self.assertEqual(stock["widget"], 8)

